void mvk_put_VkFormatProperties(MvkEncoder *e, const VkFormatProperties *s)
{
    mvk_put_u32(e, (uint32_t)(s->linearTilingFeatures));
    mvk_put_u32(e, (uint32_t)(s->optimalTilingFeatures));
    mvk_put_u32(e, (uint32_t)(s->bufferFeatures));
}

void mvk_get_VkFormatProperties(MvkDecoder *d, VkFormatProperties *s)
{
    s->linearTilingFeatures = (VkFormatFeatureFlags)mvk_get_u32(d);
    s->optimalTilingFeatures = (VkFormatFeatureFlags)mvk_get_u32(d);
    s->bufferFeatures = (VkFormatFeatureFlags)mvk_get_u32(d);
}

void mvk_put_VkImageFormatProperties(MvkEncoder *e, const VkImageFormatProperties *s)
{
    mvk_put_VkExtent3D(e, &s->maxExtent);
    mvk_put_u32(e, (uint32_t)(s->maxMipLevels));
    mvk_put_u32(e, (uint32_t)(s->maxArrayLayers));
    mvk_put_u32(e, (uint32_t)(s->sampleCounts));
    mvk_put_u64(e, (uint64_t)(s->maxResourceSize));
}

void mvk_get_VkImageFormatProperties(MvkDecoder *d, VkImageFormatProperties *s)
{
    mvk_get_VkExtent3D(d, (VkExtent3D *)&s->maxExtent);
    s->maxMipLevels = (uint32_t)mvk_get_u32(d);
    s->maxArrayLayers = (uint32_t)mvk_get_u32(d);
    s->sampleCounts = (VkSampleCountFlags)mvk_get_u32(d);
    s->maxResourceSize = (VkDeviceSize)mvk_get_u64(d);
}

void mvk_put_VkExtent3D(MvkEncoder *e, const VkExtent3D *s)
{
    mvk_put_u32(e, (uint32_t)(s->width));
    mvk_put_u32(e, (uint32_t)(s->height));
    mvk_put_u32(e, (uint32_t)(s->depth));
}

void mvk_get_VkExtent3D(MvkDecoder *d, VkExtent3D *s)
{
    s->width = (uint32_t)mvk_get_u32(d);
    s->height = (uint32_t)mvk_get_u32(d);
    s->depth = (uint32_t)mvk_get_u32(d);
}

void mvk_put_VkPhysicalDeviceProperties(MvkEncoder *e, const VkPhysicalDeviceProperties *s)
{
    mvk_put_u32(e, (uint32_t)(s->apiVersion));
    mvk_put_u32(e, (uint32_t)(s->driverVersion));
    mvk_put_u32(e, (uint32_t)(s->vendorID));
    mvk_put_u32(e, (uint32_t)(s->deviceID));
    mvk_put_u32(e, (uint32_t)(s->deviceType));
    mvk_put_bytes(e, s->deviceName, (size_t)(VK_MAX_PHYSICAL_DEVICE_NAME_SIZE) * sizeof((s->deviceName)[0]));
    mvk_put_bytes(e, s->pipelineCacheUUID, (size_t)(VK_UUID_SIZE) * sizeof((s->pipelineCacheUUID)[0]));
    mvk_put_VkPhysicalDeviceLimits(e, &s->limits);
    mvk_put_VkPhysicalDeviceSparseProperties(e, &s->sparseProperties);
}

void mvk_get_VkPhysicalDeviceProperties(MvkDecoder *d, VkPhysicalDeviceProperties *s)
{
    s->apiVersion = (uint32_t)mvk_get_u32(d);
    s->driverVersion = (uint32_t)mvk_get_u32(d);
    s->vendorID = (uint32_t)mvk_get_u32(d);
    s->deviceID = (uint32_t)mvk_get_u32(d);
    s->deviceType = (VkPhysicalDeviceType)mvk_get_u32(d);
    mvk_get_bytes(d, s->deviceName, (size_t)(VK_MAX_PHYSICAL_DEVICE_NAME_SIZE) * sizeof((s->deviceName)[0]));
    mvk_get_bytes(d, s->pipelineCacheUUID, (size_t)(VK_UUID_SIZE) * sizeof((s->pipelineCacheUUID)[0]));
    mvk_get_VkPhysicalDeviceLimits(d, (VkPhysicalDeviceLimits *)&s->limits);
    mvk_get_VkPhysicalDeviceSparseProperties(d, (VkPhysicalDeviceSparseProperties *)&s->sparseProperties);
}

