void mvk_put_VkResourceDescriptorInfoEXT(MvkEncoder *e, const VkResourceDescriptorInfoEXT *s)
{
    mvk_put_chain(e, s->pNext);
    mvk_put_u32(e, (uint32_t)(s->type));
    switch ((int)(s->type)) {
    case VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE:
    case VK_DESCRIPTOR_TYPE_STORAGE_IMAGE:
    case VK_DESCRIPTOR_TYPE_INPUT_ATTACHMENT:
    case VK_DESCRIPTOR_TYPE_BLOCK_MATCH_IMAGE_QCOM:
    case VK_DESCRIPTOR_TYPE_SAMPLE_WEIGHT_IMAGE_QCOM:
        mvk_put_u32(e, s->data.pImage ? 1 : 0);
        if (s->data.pImage)
            mvk_put_VkImageDescriptorInfoEXT(e, s->data.pImage);
        break;
    case VK_DESCRIPTOR_TYPE_UNIFORM_TEXEL_BUFFER:
    case VK_DESCRIPTOR_TYPE_STORAGE_TEXEL_BUFFER:
        mvk_put_u32(e, s->data.pTexelBuffer ? 1 : 0);
        if (s->data.pTexelBuffer)
            mvk_put_VkTexelBufferDescriptorInfoEXT(e, s->data.pTexelBuffer);
        break;
    case VK_DESCRIPTOR_TYPE_ACCELERATION_STRUCTURE_KHR:
    case VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER:
    case VK_DESCRIPTOR_TYPE_STORAGE_BUFFER:
        mvk_put_u32(e, s->data.pAddressRange ? 1 : 0);
        if (s->data.pAddressRange)
            mvk_put_VkDeviceAddressRangeKHR(e, s->data.pAddressRange);
        break;
    case VK_DESCRIPTOR_TYPE_TENSOR_ARM:
        mvk_put_u32(e, s->data.pTensorARM ? 1 : 0);
        if (s->data.pTensorARM)
            mvk_put_VkTensorViewCreateInfoARM(e, s->data.pTensorARM);
        break;
    default:
        break;
    }
}

void mvk_get_VkResourceDescriptorInfoEXT(MvkDecoder *d, VkResourceDescriptorInfoEXT *s)
{
    s->sType = VK_STRUCTURE_TYPE_RESOURCE_DESCRIPTOR_INFO_EXT;
    s->pNext = mvk_get_chain(d);
    s->type = (VkDescriptorType)mvk_get_u32(d);
    switch ((int)(s->type)) {
    case VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE:
    case VK_DESCRIPTOR_TYPE_STORAGE_IMAGE:
    case VK_DESCRIPTOR_TYPE_INPUT_ATTACHMENT:
    case VK_DESCRIPTOR_TYPE_BLOCK_MATCH_IMAGE_QCOM:
    case VK_DESCRIPTOR_TYPE_SAMPLE_WEIGHT_IMAGE_QCOM:
        if (mvk_get_u32(d)) {
            VkImageDescriptorInfoEXT *item = mvk_alloc(d, sizeof(VkImageDescriptorInfoEXT));
            mvk_get_VkImageDescriptorInfoEXT(d, item);
            s->data.pImage = item;
        } else {
            s->data.pImage = NULL;
        }
        break;
    case VK_DESCRIPTOR_TYPE_UNIFORM_TEXEL_BUFFER:
    case VK_DESCRIPTOR_TYPE_STORAGE_TEXEL_BUFFER:
        if (mvk_get_u32(d)) {
            VkTexelBufferDescriptorInfoEXT *item = mvk_alloc(d, sizeof(VkTexelBufferDescriptorInfoEXT));
            mvk_get_VkTexelBufferDescriptorInfoEXT(d, item);
            s->data.pTexelBuffer = item;
        } else {
            s->data.pTexelBuffer = NULL;
        }
        break;
    case VK_DESCRIPTOR_TYPE_ACCELERATION_STRUCTURE_KHR:
    case VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER:
    case VK_DESCRIPTOR_TYPE_STORAGE_BUFFER:
        if (mvk_get_u32(d)) {
            VkDeviceAddressRangeKHR *item = mvk_alloc(d, sizeof(VkDeviceAddressRangeKHR));
            mvk_get_VkDeviceAddressRangeKHR(d, item);
            s->data.pAddressRange = item;
        } else {
            s->data.pAddressRange = NULL;
        }
        break;
    case VK_DESCRIPTOR_TYPE_TENSOR_ARM:
        if (mvk_get_u32(d)) {
            VkTensorViewCreateInfoARM *item = mvk_alloc(d, sizeof(VkTensorViewCreateInfoARM));
            mvk_get_VkTensorViewCreateInfoARM(d, item);
            s->data.pTensorARM = item;
        } else {
            s->data.pTensorARM = NULL;
        }
        break;
    default:
        memset(&s->data, 0, sizeof(s->data));
        break;
    }
}

