    mvk_put_u32(e, (uint32_t)(s->type));
    mvk_put_u32(e, (uint32_t)(s->flags));
    mvk_put_u32(e, (uint32_t)(s->mode));
    mvk_put_handle(e, 0, (uint64_t)(s->dstMicromap));
    mvk_put_u32(e, (uint32_t)(s->usageCountsCount));
    mvk_put_u32(e, s->pUsageCounts ? 1 : 0);
    if (s->pUsageCounts) {
        for (uint32_t i = 0; i < (uint32_t)(s->usageCountsCount); i++)
            mvk_put_VkMicromapUsageEXT(e, &s->pUsageCounts[i]);
    }
    mvk_put_u32(e, s->ppUsageCounts ? 1 : 0);
    if (s->ppUsageCounts) {
        for (uint32_t i = 0; i < (uint32_t)(s->usageCountsCount); i++)
            mvk_put_VkMicromapUsageEXT(e, s->ppUsageCounts[i]);
    }
    mvk_put_bytes(e, &s->data, sizeof(s->data));
    mvk_put_bytes(e, &s->scratchData, sizeof(s->scratchData));
    mvk_put_bytes(e, &s->triangleArray, sizeof(s->triangleArray));
    mvk_put_u64(e, (uint64_t)(s->triangleArrayStride));
