    s->type = (VkMicromapTypeEXT)mvk_get_u32(d);
    s->flags = (VkBuildMicromapFlagsEXT)mvk_get_u32(d);
    s->mode = (VkBuildMicromapModeEXT)mvk_get_u32(d);
    s->dstMicromap = (VkMicromapEXT)mvk_get_handle(d, 0);
    s->usageCountsCount = (uint32_t)mvk_get_u32(d);
    if (mvk_get_u32(d)) {
        VkMicromapUsageEXT *items = mvk_alloc(d, (size_t)(s->usageCountsCount) * sizeof(VkMicromapUsageEXT));
        for (uint32_t i = 0; i < (uint32_t)(s->usageCountsCount); i++)
            mvk_get_VkMicromapUsageEXT(d, &items[i]);
        s->pUsageCounts = items;
    } else {
        s->pUsageCounts = NULL;
    }
    if (mvk_get_u32(d)) {
        VkMicromapUsageEXT **items = mvk_alloc(d, sizeof(VkMicromapUsageEXT *) * (size_t)(s->usageCountsCount));
        for (uint32_t i = 0; i < (uint32_t)(s->usageCountsCount); i++) {
            items[i] = mvk_alloc(d, sizeof(VkMicromapUsageEXT));
            mvk_get_VkMicromapUsageEXT(d, items[i]);
        }
        s->ppUsageCounts = (void *)items;
    } else {
        s->ppUsageCounts = NULL;
    }
    mvk_get_bytes(d, &s->data, sizeof(s->data));
    mvk_get_bytes(d, &s->scratchData, sizeof(s->scratchData));
    mvk_get_bytes(d, &s->triangleArray, sizeof(s->triangleArray));
    s->triangleArrayStride = (VkDeviceSize)mvk_get_u64(d);
