        break;
    case VK_DESCRIPTOR_TYPE_STORAGE_IMAGE:
        mvk_put_u32(e, s->data.pStorageImage ? 1 : 0);
        if (s->data.pStorageImage)
            mvk_put_VkDescriptorImageInfo(e, s->data.pStorageImage);
        break;
    case VK_DESCRIPTOR_TYPE_UNIFORM_TEXEL_BUFFER:
        mvk_put_u32(e, s->data.pUniformTexelBuffer ? 1 : 0);
        if (s->data.pUniformTexelBuffer)
            mvk_put_VkDescriptorAddressInfoEXT(e, s->data.pUniformTexelBuffer);
        break;
    case VK_DESCRIPTOR_TYPE_STORAGE_TEXEL_BUFFER:
        mvk_put_u32(e, s->data.pStorageTexelBuffer ? 1 : 0);
        if (s->data.pStorageTexelBuffer)
            mvk_put_VkDescriptorAddressInfoEXT(e, s->data.pStorageTexelBuffer);
        break;
    case VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER:
        mvk_put_u32(e, s->data.pUniformBuffer ? 1 : 0);
        if (s->data.pUniformBuffer)
            mvk_put_VkDescriptorAddressInfoEXT(e, s->data.pUniformBuffer);
        break;
    case VK_DESCRIPTOR_TYPE_STORAGE_BUFFER:
        mvk_put_u32(e, s->data.pStorageBuffer ? 1 : 0);
        if (s->data.pStorageBuffer)
            mvk_put_VkDescriptorAddressInfoEXT(e, s->data.pStorageBuffer);
