void mvk_put_VkFrameBoundaryEXT(MvkEncoder *e, const VkFrameBoundaryEXT *s)
{
    mvk_put_chain(e, s->pNext);
    mvk_put_u32(e, (uint32_t)(s->flags));
    mvk_put_u64(e, (uint64_t)(s->frameID));
    mvk_put_u32(e, (uint32_t)(s->imageCount));
    mvk_put_u32(e, s->pImages ? 1 : 0);
    if (s->pImages) {
        for (uint32_t i = 0; i < (uint32_t)(s->imageCount); i++)
            mvk_put_handle(e, 0, (uint64_t)(s->pImages[i]));
    }
    mvk_put_u32(e, (uint32_t)(s->bufferCount));
    mvk_put_u32(e, s->pBuffers ? 1 : 0);
    if (s->pBuffers) {
        for (uint32_t i = 0; i < (uint32_t)(s->bufferCount); i++)
            mvk_put_handle(e, 0, (uint64_t)(s->pBuffers[i]));
    }
    mvk_put_u64(e, (uint64_t)(s->tagName));
    mvk_put_u64(e, (uint64_t)(s->tagSize));
    mvk_put_blob(e, s->pTag, s->tagSize);
}

void mvk_get_VkFrameBoundaryEXT(MvkDecoder *d, VkFrameBoundaryEXT *s)
{
    s->sType = VK_STRUCTURE_TYPE_FRAME_BOUNDARY_EXT;
    s->pNext = mvk_get_chain(d);
    s->flags = (VkFrameBoundaryFlagsEXT)mvk_get_u32(d);
    s->frameID = (uint64_t)mvk_get_u64(d);
    s->imageCount = (uint32_t)mvk_get_u32(d);
    if (mvk_get_u32(d)) {
        VkImage *items = mvk_alloc(d, (size_t)(s->imageCount) * sizeof(VkImage));
        for (uint32_t i = 0; i < (uint32_t)(s->imageCount); i++)
            items[i] = (VkImage)mvk_get_handle(d, 0);
        s->pImages = items;
    } else {
        s->pImages = NULL;
    }
    s->bufferCount = (uint32_t)mvk_get_u32(d);
    if (mvk_get_u32(d)) {
        VkBuffer *items = mvk_alloc(d, (size_t)(s->bufferCount) * sizeof(VkBuffer));
        for (uint32_t i = 0; i < (uint32_t)(s->bufferCount); i++)
            items[i] = (VkBuffer)mvk_get_handle(d, 0);
        s->pBuffers = items;
    } else {
        s->pBuffers = NULL;
    }
    s->tagName = (uint64_t)mvk_get_u64(d);
    s->tagSize = (size_t)mvk_get_u64(d);
    s->pTag = (void *)mvk_get_blob(d, NULL);
}

